// evict_policy.cpp: compute eviction score
float EvictionScore(const EntryMeta &m) {
  // recency normalized [0,1], size in bytes, frag_cost estimated in pages
  float r = RecencyScore(m.last_access_ns);
  float s = SizePenalty(m.size_bytes);
  float f = FragmentationPenalty(m.fragmentation_pages);
  float p = PriorityMultiplier(m.priority);
  // higher score -> evict earlier
  return (0.6f * r) + (0.25f * s) + (0.1f * f) * p;
}
// compactor.cpp: background compaction loop
while (!shutdown) {
  if (!shouldRunCompaction()) { sleep(); continue; }
  auto shard = pickWorstFragmentedShard();
  acquireShardLock(shard);
  coalesceEntries(shard);
  releaseShardLock(shard);
}
